:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --accent: #ffb347;
  --accent-hover: #ffa020;
  --accent-pressed: #e68a00;
  --bar-bg: #3a3a55;
  --hunger: #ff6b6b;
  --happiness: #ffd93d;
  --energy: #6bcb77;
  --focus: #ffb347;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 24px 20px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 16px;
  letter-spacing: 1px;
}

.pet-stage {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pixel-pet {
  position: relative;
  width: 120px;
  height: 120px;
  image-rendering: pixelated;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: #8b5e3c;
  border-radius: 12px;
  position: relative;
  box-shadow: inset -8px -8px 0 rgba(0,0,0,0.2);
}

.pet-eye {
  position: absolute;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 2px;
  top: 30%;
}

.pet-eye.left { left: 25%; }
.pet-eye.right { right: 25%; }

.pet-eye::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  background: #222;
  border-radius: 50%;
  top: 4px;
  left: 4px;
}

.pet-mouth {
  position: absolute;
  width: 24px;
  height: 8px;
  background: #222;
  border-radius: 0 0 12px 12px;
  bottom: 25%;
  left: 50%;
  transform: translateX(-50%);
}

.mood-text {
  font-size: 1.125rem;
  margin-bottom: 20px;
  min-height: 1.5em;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.stat {
  text-align: left;
}

.stat-label {
  display: block;
  font-size: 0.875rem;
  margin-bottom: 4px;
  opacity: 0.8;
}

.bar {
  background: var(--bar-bg);
  border-radius: 8px;
  height: 20px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.hunger-fill { background: var(--hunger); }
.happiness-fill { background: var(--happiness); }
.energy-fill { background: var(--energy); }

.actions {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.action-btn {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  border-radius: 12px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  flex: 1;
  min-width: 80px;
}

.action-btn:hover {
  background: var(--accent-hover);
}

.action-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.96);
}

.action-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 360px) {
  .game-card {
    padding: 16px 12px;
  }
  .action-btn {
    padding: 10px 14px;
    font-size: 0.9rem;
  }
  h1 {
    font-size: 1.5rem;
  }
}

const state = {
  hunger: 20,
  happiness: 80,
  energy: 70
};

const hungerFill = document.getElementById('hunger-fill');
const happinessFill = document.getElementById('happiness-fill');
const energyFill = document.getElementById('energy-fill');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood-text');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';

  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.setAttribute('aria-valuenow', state.energy);

  let mood = '';
  if (state.hunger > 70) mood = 'Your pet is starving!';
  else if (state.energy < 30) mood = 'Your pet is exhausted.';
  else if (state.happiness < 30) mood = 'Your pet is sad.';
  else if (state.hunger < 30 && state.happiness > 60 && state.energy > 60) mood = 'Your pet is feeling great!';
  else mood = 'Your pet is doing okay.';

  moodText.textContent = mood;
}

function feed() {
  state.hunger = clamp(state.hunger - 25);
  state.happiness = clamp(state.happiness + 5);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger + 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger + 10);
  state.happiness = clamp(state.happiness - 10);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
